import {
  mkdir,
  readFile,
  writeFile,
  appendFile,
  readdir,
  rm,
  stat,
} from "node:fs/promises";
import path from "node:path";
import { randomUUID, createHash } from "node:crypto";
import { fail } from "./store.js";

export const MAX_TRANSFER_BYTES = 32 * 1024 * 1024;
export const TRANSFER_CHUNK_BYTES = 256 * 1024;
const digest = (bytes) => createHash("sha256").update(bytes).digest("hex");
// Transfer IDs are generated by the server. No caller-supplied filesystem paths.
export class McpTransfers {
  constructor(store) {
    this.store = store;
    this.directory = path.join(store.dir, "transfers");
  }
  files(id) {
    if (!/^[0-9a-f-]{36}$/.test(id))
      throw fail("RESOURCE_DENIED", "传输ID无效");
    return {
      meta: path.join(this.directory, id + ".json"),
      data: path.join(this.directory, id + ".bin"),
    };
  }
  async prune() {
    await mkdir(this.directory, { recursive: true, mode: 0o700 });
    for (const file of await readdir(this.directory)) {
      if (!/^[0-9a-f-]{36}\.json$/.test(file)) continue;
      const meta = JSON.parse(
        await readFile(path.join(this.directory, file), "utf8"),
      );
      if (Date.parse(meta.expiresAt) > Date.now()) continue;
      const files = this.files(file.slice(0, -5));
      await rm(files.data, { force: true });
      await rm(files.meta, { force: true });
    }
  }
  async meta(client, id) {
    let meta;
    try {
      meta = JSON.parse(await readFile(this.files(id).meta, "utf8"));
    } catch {
      throw fail("RESOURCE_DENIED", "传输不存在");
    }
    if (meta.clientId !== client.id || Date.parse(meta.expiresAt) <= Date.now())
      throw fail("RESOURCE_DENIED", "传输不属于当前客户端或已过期");
    return meta;
  }
  async stage(
    client,
    { transferId, fileName, totalBytes, sha256, offset, dataBase64 },
  ) {
    return this.store.serial(async () => {
      await this.prune();
      if (!/^[A-Za-z0-9+/]*={0,2}$/.test(dataBase64) || dataBase64.length % 4)
        throw fail("VALIDATION_FAILED", "需要标准Base64", 422);
      const bytes = Buffer.from(dataBase64, "base64");
      if (!bytes.length || bytes.length > TRANSFER_CHUNK_BYTES)
        throw fail("VALIDATION_FAILED", "分块需为1至256KiB", 422);
      let meta;
      if (!transferId) {
        if (
          offset !== 0 ||
          !Number.isInteger(totalBytes) ||
          totalBytes < 1 ||
          totalBytes > MAX_TRANSFER_BYTES ||
          !/^[a-f0-9]{64}$/.test(sha256 || "") ||
          !fileName ||
          /[/\\\x00-\x1f]/.test(fileName)
        )
          throw fail(
            "VALIDATION_FAILED",
            "首次分块需提供文件名、总大小和SHA256",
            422,
          );
        const owned = [];
        for (const f of await readdir(this.directory))
          if (f.endsWith(".json")) {
            const m = JSON.parse(
              await readFile(path.join(this.directory, f), "utf8"),
            );
            if (m.clientId === client.id) owned.push(m);
          }
        if (owned.length >= 8)
          throw fail(
            "BUDGET_EXCEEDED",
            "每客户端最多8项暂存传输；一小时后按需清理",
          );
        transferId = randomUUID();
        meta = {
          transferId,
          clientId: client.id,
          fileName,
          totalBytes,
          sha256,
          receivedBytes: 0,
          expiresAt: new Date(Date.now() + 3600000).toISOString(),
        };
        await writeFile(this.files(transferId).data, Buffer.alloc(0), {
          flag: "wx",
          mode: 0o600,
        });
        await writeFile(this.files(transferId).meta, JSON.stringify(meta), {
          mode: 0o600,
        });
      } else meta = await this.meta(client, transferId);
      if (meta.exported) throw fail("RESOURCE_DENIED", "导出传输不可追加");
      const files = this.files(transferId),
        size = (await stat(files.data)).size;
      if (offset < size) {
        const previous = await readFile(files.data);
        if (
          offset + bytes.length > size ||
          !previous.subarray(offset, offset + bytes.length).equals(bytes)
        )
          throw fail("REVISION_CONFLICT", "分块偏移冲突", 409);
      } else {
        if (offset !== size || offset + bytes.length > meta.totalBytes)
          throw fail("REVISION_CONFLICT", "分块偏移或总大小不一致", 409);
        await appendFile(files.data, bytes);
      }
      meta.receivedBytes = (await stat(files.data)).size;
      meta.complete = meta.receivedBytes === meta.totalBytes;
      if (meta.complete && digest(await readFile(files.data)) !== meta.sha256) {
        await rm(files.data, { force: true });
        await rm(files.meta, { force: true });
        throw fail(
          "VALIDATION_FAILED",
          "文件SHA256不一致，已清理该暂存，请重新上传",
          422,
        );
      }
      await writeFile(files.meta, JSON.stringify(meta), { mode: 0o600 });
      return {
        transferId,
        receivedBytes: meta.receivedBytes,
        totalBytes: meta.totalBytes,
        complete: meta.complete,
        expiresAt: meta.expiresAt,
      };
    });
  }
  async bytes(client, id) {
    const meta = await this.meta(client, id),
      bytes = await readFile(this.files(id).data);
    if (
      !meta.complete ||
      bytes.length !== meta.totalBytes ||
      digest(bytes) !== meta.sha256
    )
      throw fail("VALIDATION_FAILED", "文件不完整或校验失败", 422);
    return { meta, bytes };
  }
  async export(client, fileName, bytes) {
    await this.prune();
    let owned = 0;
    for (const file of await readdir(this.directory))
      if (file.endsWith(".json")) {
        const meta = JSON.parse(
          await readFile(path.join(this.directory, file), "utf8"),
        );
        if (meta.clientId === client.id) owned++;
      }
    if (owned >= 8)
      throw fail(
        "BUDGET_EXCEEDED",
        "每客户端最多8项暂存传输，请先清理不用的导出文件",
      );
    if (bytes.length > MAX_TRANSFER_BYTES)
      throw fail("BUDGET_EXCEEDED", "导出包超过32MiB，请使用实例导出");
    const transferId = randomUUID(),
      files = this.files(transferId);
    const meta = {
      transferId,
      clientId: client.id,
      fileName,
      totalBytes: bytes.length,
      sha256: digest(bytes),
      receivedBytes: bytes.length,
      complete: true,
      exported: true,
      expiresAt: new Date(Date.now() + 3600000).toISOString(),
    };
    await writeFile(files.data, bytes, { mode: 0o600 });
    await writeFile(files.meta, JSON.stringify(meta), { mode: 0o600 });
    return {
      transferId,
      fileName,
      totalBytes: meta.totalBytes,
      sha256: meta.sha256,
      chunkBytes: TRANSFER_CHUNK_BYTES,
      expiresAt: meta.expiresAt,
    };
  }
  async read(client, id, offset) {
    const { meta, bytes } = await this.bytes(client, id);
    if (offset > bytes.length)
      throw fail("VALIDATION_FAILED", "偏移超出文件", 422);
    const end = Math.min(offset + TRANSFER_CHUNK_BYTES, bytes.length);
    return {
      transferId: id,
      offset,
      nextOffset: end,
      totalBytes: bytes.length,
      sha256: meta.sha256,
      dataBase64: bytes.subarray(offset, end).toString("base64"),
      complete: end === bytes.length,
    };
  }
  async discard(client, id) {
    await this.meta(client, id);
    const referenced = this.store.state.plans.some((p) => {
      if (p.clientId !== client.id || Date.parse(p.expiresAt) <= Date.now())
        return false;
      return (
        p.payload?.value?.transferId === id ||
        p.before?.modelAsset?.transferId === id
      );
    });
    if (referenced)
      throw fail(
        "RESOURCE_DENIED",
        "暂存文件仍用于有效计划或模型恢复快照，将在到期后按需清理",
      );
    const files = this.files(id);
    await rm(files.data, { force: true });
    await rm(files.meta, { force: true });
    return { removed: true };
  }
}
